<script setup lang="ts">
import {onMounted,ref,watch,computed,nextTick} from 'vue'
import type {components} from '../../shared/api'
import type {SessionClient} from '../auth/session'
import ScheduleFields from './ScheduleFields.vue'
type Template=components['schemas']['RitualView'];type Assignment=components['schemas']['RitualAssignmentView'];type Occurrence=components['schemas']['OccurrenceView'];type Schedule=components['schemas']['Schedule']
const props=defineProps<{client:SessionClient;ru:boolean;me:components['schemas']['MemberView'];participants:components['schemas']['ParticipantView'][]}>()
const t=(en:string,ru:string)=>props.ru?ru:en
const templates=ref<Template[]>([]),assignments=ref<Assignment[]>([]),occurrences=ref<Occurrence[]>([]),notices=ref<components['schemas']['RitualNoticeView'][]>([])
const modal=ref<HTMLDialogElement|null>(null)
const busy=ref(false),error=ref(''),success=ref(''),filter=ref('all'),history=ref<Template[]>([])
const editor=ref(false),selected=ref<Template|null>(null),title=ref(''),description=ref('')
function today(zone:string){return new Intl.DateTimeFormat('en-CA',{timeZone:zone,year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())}
function initial():Schedule{return {kind:'daily',timezone:props.me.timezone,hour:9,minute:0,start_date:today(props.me.timezone),weekdays:[],window_hours:24}}
const assigning=ref<Template|null>(null),rescheduling=ref<Assignment|null>(null),recipient=ref(''),reviewers=ref<string[]>([]),approval=ref(true),schedule=ref<Schedule>(initial()),assignKey=ref(crypto.randomUUID())
const reporting=ref<Occurrence|null>(null),reviewing=ref<Occurrence|null>(null),reportText=ref(''),comment=ref(''),reportKey=ref(crypto.randomUUID())
const visible=computed(()=>occurrences.value.filter(o=>filter.value==='all'||o.status===filter.value))
const name=(id:string)=>props.participants.find(p=>p.id===id)?.display_name??id
const time=(value:string)=>new Intl.DateTimeFormat(props.ru?'ru-RU':'en-GB',{dateStyle:'medium',timeStyle:'short'}).format(new Date(value))
async function load(){templates.value=await props.client.get('/rituals');assignments.value=await props.client.get('/ritual-assignments');occurrences.value=await props.client.get('/ritual-occurrences');notices.value=await props.client.get('/ritual-notices')}
async function run(fn:()=>Promise<void>){busy.value=true;error.value='';success.value='';try{await fn()}catch(e){error.value=e instanceof Error?e.message:'NETWORK_ERROR'}finally{busy.value=false}}
onMounted(()=>run(load))
watch(()=>props.me.paused,()=>{occurrences.value=occurrences.value.map(o=>({...o,can_report:false,can_review:false}));void run(load)})
watch(recipient,id=>{reviewers.value=reviewers.value.filter(r=>r!==id)})
watch([recipient,reviewers,approval,schedule],()=>{assignKey.value=crypto.randomUUID()},{deep:true})
watch(reportText,()=>{reportKey.value=crypto.randomUUID()})
watch([reporting,reviewing],async()=>{await nextTick();if(reporting.value||reviewing.value){if(!modal.value?.open)modal.value?.showModal()}else modal.value?.close()})
function edit(r:Template|null){selected.value=r;title.value=r?.title??'';description.value=r?.description??'';editor.value=true;assigning.value=null}
async function save(){await run(async()=>{const r=selected.value,body={title:title.value,description:description.value};if(!r)await props.client.post('/rituals',body);else if(r.status==='draft')await props.client.patch(`/rituals/${r.id}`,{...body,expected_version:r.revision});else await props.client.post(`/rituals/${r.id}/versions`,{...body,expected_version:r.revision});editor.value=false;await load()})}
async function templateAction(r:Template,action:string){await run(async()=>{await props.client.post(`/rituals/${r.id}/${action}`,{expected_version:r.revision});await load()})}
function startAssign(r:Template){assigning.value=r;rescheduling.value=null;recipient.value='';reviewers.value=[];schedule.value=initial();approval.value=true;editor.value=false}
function startSchedule(a:Assignment){rescheduling.value=a;assigning.value=null;const date=new Date();date.setDate(date.getDate()+1);schedule.value={...a.schedule,start_date:new Intl.DateTimeFormat('en-CA',{timeZone:a.schedule.timezone,year:'numeric',month:'2-digit',day:'2-digit'}).format(date)}}
async function assign(){await run(async()=>{const r=assigning.value;if(!r)return;await props.client.post(`/rituals/${r.id}/assignments`,{recipient_id:recipient.value,reviewer_ids:reviewers.value.filter(id=>id!==recipient.value),approval_required:approval.value,schedule:schedule.value,idempotency_key:assignKey.value});assigning.value=null;await load();success.value=t('Assignment created','Назначение создано')})}
async function saveSchedule(){await run(async()=>{const a=rescheduling.value;if(!a)return;await props.client.put(`/ritual-assignments/${a.id}/schedule`,{expected_version:a.revision,schedule:schedule.value});rescheduling.value=null;await load()})}
async function assignmentAction(a:Assignment,action:string){await run(async()=>{await props.client.post(`/ritual-assignments/${a.id}/${action}`,{expected_version:a.revision});await load()})}
function startReport(o:Occurrence){reporting.value=o;reportText.value='';reportKey.value=crypto.randomUUID();reviewing.value=null}
async function submit(){await run(async()=>{const o=reporting.value;if(!o)return;await props.client.post(`/ritual-occurrences/${o.id}/report`,{expected_version:o.revision,idempotency_key:reportKey.value,text:reportText.value});reporting.value=null;await load()})}
async function review(decision:'approved'|'needs_changes'){await run(async()=>{const o=reviewing.value;if(!o)return;await props.client.post(`/ritual-occurrences/${o.id}/review`,{expected_version:o.revision,decision,comment:comment.value});reviewing.value=null;await load()})}
async function skip(o:Occurrence){await run(async()=>{await props.client.post(`/ritual-occurrences/${o.id}/skip`,{expected_version:o.revision});await load()})}
async function versionHistory(r:Template){await run(async()=>{history.value=await props.client.get(`/rituals/${r.id}/versions`)})}
</script>
<template>
 <section id="rituals" class="ritual-workspace" aria-labelledby="rituals-title">
  <div class="section-heading"><div><h2 id="rituals-title">{{t('Rituals','Ритуалы')}}</h2><p class="muted">{{t('A little intention. A shared rhythm.','Немного внимания. Общий ритм.')}}</p></div><div><button :disabled="busy" @click="run(load)">{{t('Refresh rituals','Обновить ритуалы')}}</button><button :disabled="busy||me.paused" @click="edit(null)">{{t('New ritual','Новый ритуал')}}</button></div></div>
  <p v-if="busy" role="status">{{t('Loading rituals…','Загружаем ритуалы…')}}</p><p v-if="error" role="alert">{{error}} · {{t('Refresh to load the current state.','Обновите данные для актуального состояния.')}}</p><p v-if="success" role="status">{{success}}</p>
  <div class="ritual-summary"><div><strong>{{occurrences.filter(o=>o.recipient_id===me.id&&o.status==='scheduled').length}}</strong><span>{{t('Planned for you','Ваши выполнения')}}</span></div><div><strong>{{occurrences.filter(o=>o.can_review).length}}</strong><span>{{t('Awaiting your review','Ждут вашей проверки')}}</span></div><div><strong>{{occurrences.filter(o=>o.status==='approved').length}}</strong><span>{{t('Approved','Одобрено')}}</span></div></div>
  <div class="ritual-columns"><div>
   <div class="section-heading"><h3>{{t('Your rhythm','Ваш ритм')}}</h3><label class="filter-label">{{t('Status','Статус')}}<select v-model="filter"><option value="all">{{t('All','Все')}}</option><option v-for="status in ['scheduled','submitted','needs_changes','approved','missed','skipped','cancelled']" :key="status">{{status}}</option></select></label></div>
   <p v-if="!visible.length" class="empty-state">{{t('No visible occurrences. Create a template and assign it with an agreed scope.','Нет доступных выполнений. Создайте шаблон и назначьте его в согласованной связи.')}}</p>
   <article v-for="o in visible" :key="o.id" class="occurrence-row">
    <div class="occurrence-heading"><div><h4>{{o.title}}</h4><p class="muted">{{name(o.recipient_id)}} · <time :datetime="o.due_at">{{time(o.due_at)}}</time></p></div><span class="status-tag" :data-status="o.status">{{o.status}}</span></div>
    <p>{{o.description}}</p><p class="muted">{{t('Report until','Отчёт до')}} {{time(o.expires_at)}}</p>
    <details v-if="o.reports.length" open><summary>{{t('Report history','История отчётов')}} · {{o.reports.length}}</summary><div v-for="r in o.reports" :key="r.id" class="report-attempt"><p class="muted">{{t('Attempt','Попытка')}} {{r.attempt}} · {{time(r.submitted_at)}}</p><p>{{r.text}}</p><p v-if="r.decision">{{r.decision}} · {{r.reviewer_id?name(r.reviewer_id):''}}</p><p v-if="r.comment">{{r.comment}}</p></div></details>
    <button v-if="o.can_report&&!me.paused" :disabled="busy" @click="startReport(o)">{{t('Write report','Написать отчёт')}}</button>
    <button v-if="o.can_review&&!me.paused" :disabled="busy" @click="reviewing=o;comment='';reporting=null">{{t('Review report','Проверить отчёт')}}</button>
    <button v-if="o.recipient_id===me.id&&['scheduled','needs_changes'].includes(o.status)" class="secondary" :disabled="busy" @click="skip(o)">{{t('Skip occurrence','Пропустить выполнение')}}</button>
   </article>
  </div><aside class="ritual-notifications"><h3>{{t('Updates','Обновления')}}</h3><p v-if="!notices.length" class="muted">{{t('No updates yet','Пока нет обновлений')}}</p><div v-for="n in notices.slice(0,5)" :key="n.id" class="notice-row"><p>{{t('You have an update in the app','У вас есть обновление в приложении')}}</p><time class="muted" :datetime="n.created_at">{{time(n.created_at)}}</time></div></aside></div>
  <form v-if="editor" class="ritual-editor" @submit.prevent="save"><h3>{{selected?t('Ritual version','Версия ритуала'):t('Create a ritual','Создать ритуал')}}</h3><label>{{t('Ritual title','Название ритуала')}}<input v-model="title" maxlength="200" required></label><label>{{t('Ritual description','Описание ритуала')}}<textarea v-model="description" maxlength="10000" rows="4" required /></label><button :disabled="busy||me.paused">{{t('Save ritual','Сохранить ритуал')}}</button><button type="button" class="secondary" :disabled="busy" @click="editor=false">{{t('Cancel','Отмена')}}</button></form>
  <details class="ritual-library" open><summary>{{t('Ritual library','Библиотека ритуалов')}}</summary><p v-if="!templates.length" class="muted">{{t('Your authored templates will appear here.','Здесь появятся созданные вами шаблоны.')}}</p><article v-for="r in templates" :key="r.id"><h4>{{r.title}}</h4><p>{{r.description}}</p><p class="muted">{{r.status}} · {{r.version_id}}</p><button :disabled="busy||me.paused" @click="edit(r)">{{r.status==='draft'?t('Edit ritual draft','Изменить черновик ритуала'):t('New ritual version','Новая версия ритуала')}}</button><button v-if="r.status==='draft'" :disabled="busy||me.paused" @click="templateAction(r,'publish')">{{t('Publish ritual','Опубликовать ритуал')}}</button><button v-if="r.status==='published'" :disabled="busy||me.paused" @click="startAssign(r)">{{t('Assign ritual','Назначить ритуал')}}</button><button :disabled="busy" class="secondary" @click="versionHistory(r)">{{t('Ritual version history','История версий ритуала')}}</button><button v-if="r.status!=='archived'" :disabled="busy" class="secondary" @click="templateAction(r,'archive')">{{t('Archive ritual','Архивировать ритуал')}}</button></article></details>
  <div v-if="history.length"><h3>{{t('Version history','История версий')}}</h3><article v-for="v in history" :key="v.version_id"><h4>{{v.title}}</h4><p>{{v.description}}</p><p class="muted">{{v.status}} · {{v.version_id}}</p></article><button class="secondary" @click="history=[]">{{t('Close history','Закрыть историю')}}</button></div>
  <form v-if="assigning||rescheduling" class="ritual-editor" @submit.prevent="rescheduling?saveSchedule():assign()"><h3>{{assigning?.title??rescheduling?.title}}</h3><template v-if="assigning"><label>{{t('Ritual recipient','Адресат ритуала')}}<select v-model="recipient" required><option value="" disabled>—</option><option v-for="p in participants.filter(p=>p.id!==me.id)" :key="p.id" :value="p.id">{{p.display_name}}</option></select></label><fieldset><legend>{{t('Explicit reviewers','Назначенные проверяющие')}}</legend><label v-for="p in participants.filter(p=>p.id!==recipient)" :key="p.id"><input v-model="reviewers" type="checkbox" :value="p.id">{{t('Reviewer: ','Проверяющий: ')}}{{p.display_name}}</label></fieldset><label><input v-model="approval" type="checkbox">{{t('Approval required','Требуется проверка')}}</label></template><ScheduleFields v-model="schedule" :ru="ru" :fixed-zone="!!rescheduling" /><p v-if="rescheduling" class="muted">{{t('Changes begin tomorrow or later. Timezone changes require a new assignment.','Изменения — со следующего дня. Для смены часового пояса нужно новое назначение.')}}</p><button :disabled="busy||me.paused||(!!assigning&&approval&&!reviewers.length)">{{rescheduling?t('Save schedule','Сохранить расписание'):t('Create ritual assignment','Создать назначение ритуала')}}</button><button type="button" class="secondary" @click="assigning=null;rescheduling=null">{{t('Cancel','Отмена')}}</button></form>
  <h3>{{t('Assignments','Назначения')}}</h3><article v-for="a in assignments" :key="a.id"><h4>{{a.title}}</h4><p class="muted">{{name(a.recipient_id)}} · {{a.status}} · {{a.schedule.kind}} {{String(a.schedule.hour).padStart(2,'0')}}:{{String(a.schedule.minute).padStart(2,'0')}} {{a.schedule.timezone}}</p><button v-if="a.issuer_id===me.id&&a.effective" :disabled="busy" @click="startSchedule(a)">{{t('Change schedule','Изменить расписание')}}</button><button v-if="a.status==='active'&&(a.recipient_id===me.id||a.issuer_id===me.id)" :disabled="busy" class="secondary" @click="assignmentAction(a,'pause')">{{t('Pause ritual','Приостановить ритуал')}}</button><button v-if="a.status==='paused'&&a.recipient_id===me.id" :disabled="busy||me.paused" @click="assignmentAction(a,'resume')">{{t('Resume ritual','Возобновить ритуал')}}</button><button v-if="a.status!=='revoked'&&(a.recipient_id===me.id||a.issuer_id===me.id)" :disabled="busy" class="secondary" @click="assignmentAction(a,'revoke')">{{t('Revoke ritual','Отозвать ритуал')}}</button></article>
  <dialog ref="modal" @cancel="busy?$event.preventDefault():(reporting=null,reviewing=null)" aria-modal="true" :aria-label="reporting?t('Ritual report','Отчёт ритуала'):t('Review ritual report','Проверка отчёта ритуала')" class="ritual-dialog"><template v-if="reporting||reviewing"><h3>{{(reporting??reviewing)?.title}}</h3><form v-if="reporting" @submit.prevent="submit"><label>{{t('Ritual report','Отчёт ритуала')}}<textarea v-model="reportText" maxlength="10000" rows="6" required /></label><button :disabled="busy||me.paused">{{t('Submit report','Отправить отчёт')}}</button></form><template v-if="reviewing"><p>{{reviewing.reports.at(-1)?.text}}</p><label>{{t('Review comment','Комментарий проверяющего')}}<textarea v-model="comment" rows="4" maxlength="10000" /></label><button :disabled="busy||me.paused" @click="review('approved')">{{t('Approve report','Одобрить отчёт')}}</button><button :disabled="busy||me.paused" class="secondary" @click="review('needs_changes')">{{t('Request changes','Вернуть на доработку')}}</button></template><button :disabled="busy" class="secondary" @click="reporting=null;reviewing=null">{{t('Cancel','Отмена')}}</button><p v-if="error" role="alert">{{error}}</p></template></dialog>
 </section>
</template>
